namespace sv_9f8b653e849f4ec6a217a79ae80c2123.Services;

public class WarehouseState
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }

    public IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("WH-001", "Warehouse A — Main"),
        ("WH-002", "Warehouse B — East"),
        ("WH-003", "Warehouse C — West"),
    ];
}

namespace sv_9f8b653e849f4ec6a217a79ae80c2123.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts per warehouse.
/// Fires OnAlertCountChanged so all subscribed components re-render.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int LatestLowStockCount { get; private set; }

    public event Action? OnAlertCountChanged;

    /// <summary>Simulates a database query returning low-stock item count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB call with random result 0–15
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by the polling component to refresh the count and notify all subscribers.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        LatestLowStockCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }
}

