@using sv_9f8b653e849f4ec6a217a79ae80c2123.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard — @CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Site</h5>
        <p class="card-text fs-4">@CurrentWarehouseName</p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            <span class="fs-2 fw-bold @CountClass">@AlertService.LatestLowStockCount</span>
            <span class="ms-2 text-muted">items below minimum level</span>
        </p>
        <small class="text-muted">Auto-refreshes every 10 seconds while this page is open.</small>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    private string CurrentWarehouseName =>
        WarehouseState.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
        ?? WarehouseState.CurrentWarehouseId;

    private string CountClass => AlertService.LatestLowStockCount > 5
        ? "text-danger" : AlertService.LatestLowStockCount > 0
        ? "text-warning" : "text-success";

    protected override async Task OnInitializedAsync()
    {
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            StateHasChanged();
        });
        WarehouseState.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        // Initial fetch
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);

        // Start polling
        StartPolling();
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await InvokeAsync(async () =>
                {
                    await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
                });
            }
        }
        catch (OperationCanceledException) { }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();

        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

